(()=>{'use strict';const root=document.getElementById('courseBuilder');if(!root)return;
const lists=[...root.querySelectorAll('[data-order-kind]')],nodes=[...root.querySelectorAll('.cb-node')],blocks=[...root.querySelectorAll('.cb-block')],status=document.getElementById('courseSaveStatus'),search=document.getElementById('courseSearch');let busy=false,failed=false,filtered=false;const sortables=[];
const ids=list=>[...list.children].map(el=>el.dataset.id);
const clean=text=>text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
document.getElementById('nodeCount').textContent=nodes.length;document.getElementById('blockCount').textContent=blocks.length;document.getElementById('draftCount').textContent=nodes.filter(n=>n.dataset.published==='0').length;
function update(){root.querySelectorAll('[data-move]').forEach(button=>{const item=button.closest('[data-id]');button.disabled=busy||failed||filtered||!(button.dataset.move==='up'?item.previousElementSibling:item.nextElementSibling);});sortables.forEach(s=>s.option('disabled',busy||failed||filtered));search.disabled=busy;}
async function save(list,previous){if(ids(list).join(',')===previous.join(','))return;busy=true;update();status.classList.remove('error');status.textContent='Enregistrement de l’ordre…';const data=new FormData();data.append('_token',root.dataset.token);data.append('kind',list.dataset.orderKind);data.append('parentId',list.dataset.parentId);ids(list).forEach(id=>data.append('ids[]',id));previous.forEach(id=>data.append('previous[]',id));const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);
try{const response=await fetch(root.dataset.url,{method:'POST',body:data,headers:{'X-Requested-With':'XMLHttpRequest'},signal:controller.signal});const json=await response.json().catch(()=>null);if(!response.ok||!json?.ok)throw new Error(json?.message||'Enregistrement non confirmé. Rechargez pour vérifier l’ordre.');status.textContent='Ordre enregistré';refreshOutline();}catch(error){const map=new Map([...list.children].map(el=>[el.dataset.id,el]));previous.forEach(id=>list.append(map.get(id)));failed=true;status.classList.add('error');status.textContent=error.name==='AbortError'?'Le serveur ne répond pas. Rechargez pour vérifier l’ordre.':error.message;const link=document.createElement('a');link.href=location.href;link.textContent='Recharger la page';status.append(link);}finally{clearTimeout(timeout);busy=false;update();}}
function refreshOutline(){const nav=root.querySelector('.cb-outline nav'),top=root.querySelector('.cb-list');if(!top)return;[...top.children].forEach((item,i)=>{const link=nav.querySelector(`[href="#${item.id}"]`);if(link){link.querySelector('span').textContent=String(i+1).padStart(2,'0');nav.append(link);}});}
lists.forEach(list=>{if(window.Sortable){let previous=[];sortables.push(new Sortable(list,{animation:160,handle:'.cb-grip',draggable:'>li',ghostClass:'cb-ghost',onStart:()=>{previous=ids(list);},onEnd:()=>save(list,previous)}));}});
function expand(node,open){node.querySelector(':scope > .cb-node-body').hidden=!open;const button=node.querySelector(':scope > .cb-node-head [data-toggle-node]');button.setAttribute('aria-expanded',String(open));button.querySelector('i').className=open?'bi bi-chevron-down':'bi bi-chevron-right';}
root.addEventListener('click',event=>{const jump=event.target.closest('.cb-outline a');if(jump){if(search.value){search.value='';search.dispatchEvent(new Event('input'));}const target=document.getElementById(jump.hash.slice(1));if(target)expand(target,true);}const move=event.target.closest('[data-move]');if(move&&!move.disabled){const item=move.closest('[data-id]'),list=item.parentElement,previous=ids(list),neighbor=move.dataset.move==='up'?item.previousElementSibling:item.nextElementSibling;if(!neighbor)return;if(move.dataset.move==='up')list.insertBefore(item,neighbor);else list.insertBefore(neighbor,item);save(list,previous);return;}const toggle=event.target.closest('[data-toggle-node]');if(toggle)expand(toggle.closest('.cb-node'),toggle.getAttribute('aria-expanded')!=='true');const all=event.target.closest('[data-expand]');if(all)nodes.forEach(node=>expand(node,all.dataset.expand==='true'));});
let expandedBeforeSearch=null;
search.addEventListener('input',()=>{const term=clean(search.value.trim());filtered=!!term;root.classList.toggle('is-filtered',filtered);if(filtered&&!expandedBeforeSearch)expandedBeforeSearch=new Map(nodes.map(n=>[n,n.querySelector('[data-toggle-node]').getAttribute('aria-expanded')==='true']));nodes.forEach(n=>n.hidden=false);blocks.forEach(b=>b.hidden=false);if(filtered){[...nodes].reverse().forEach(node=>{const own=clean(node.dataset.title).includes(term),parentMatch=(()=>{let p=node.parentElement.closest('.cb-node');while(p){if(clean(p.dataset.title).includes(term))return true;p=p.parentElement.closest('.cb-node');}return false;})();const matches=own||parentMatch;node.querySelectorAll(':scope > .cb-node-body > .cb-blocks > .cb-block').forEach(b=>b.hidden=!matches&&!clean(b.textContent).includes(term));node.hidden=!matches&&![...node.querySelectorAll('.cb-block,.cb-node')].some(el=>!el.hidden);if(!node.hidden)expand(node,true);});}else if(expandedBeforeSearch){expandedBeforeSearch.forEach((open,node)=>expand(node,open));expandedBeforeSearch=null;}document.getElementById('courseNoResults').hidden=!filtered||nodes.some(n=>!n.hidden);update();});
window.addEventListener('beforeunload',event=>{if(busy){event.preventDefault();event.returnValue='';}});update();
})();
